import { describe, expect, it, vi } from 'vitest'

describe('spies', () => {
  it('tracks and can replace an object method', () => {
    const market = { getApples: () => 100 }
    const spy = vi.spyOn(market, 'getApples')

    expect(market.getApples()).toBe(100)
    expect(spy).toHaveBeenCalledTimes(1)

    spy.mockReturnValue(42)
    expect(market.getApples()).toBe(42)
    spy.mockRestore()
  })

  it('creates a standalone mock', () => {
    const callback = vi.fn((value: string) => value.toUpperCase())
    expect(callback('hello')).toBe('HELLO')
    expect(callback).toHaveBeenCalledWith('hello')
  })
})

