import { afterEach, beforeEach, describe, expect, it } from 'vitest'

const state = { value: 0 }

describe('state', () => {
  beforeEach(() => {
    state.value = 0
  })

  afterEach(() => {
    state.value = 0
  })

  it('starts clean', () => {
    state.value++
    expect(state.value).toBe(1)
  })

  it('is reset for the next test', () => {
    expect(state.value).toBe(0)
  })
})

